import {lessons,references,glossary} from './content.js';
import {mountLab,hero} from './labs.js';
import {esc} from './viz.js';
const main=document.querySelector('#main'),content=document.querySelector('#content');
let current='',observer,dataPromise,termPopover,toastTimer;
let complete=new Set();
try{complete=new Set(JSON.parse(localStorage.getItem('resampler-lessons')||'[]').filter(id=>lessons.some(l=>l.id===id)));}catch{}
function loadData(){return dataPromise??=(fetch('data/results.json').then(r=>{if(!r.ok)throw Error('The benchmark export could not load.');return r.json();}).catch(e=>{dataPromise=null;throw e;}));}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2500);}
function saveProgress(){try{localStorage.setItem('resampler-lessons',JSON.stringify([...complete]));}catch{toast('This browser cannot save progress.');}drawNav();}
function drawNav(){let group='';document.querySelector('#lesson-nav').innerHTML=lessons.map((l,i)=>{const heading=l.group!==group?`<div class="nav-group">${esc(l.group)}</div>`:'';group=l.group;return heading+`<a class="nav-link ${l.id===current?'active':''}" href="#/${l.id}" ${l.id===current?'aria-current="page"':''}><span class="nav-number">${String(i+1).padStart(2,'0')}</span>${esc(l.title)}${complete.has(l.id)?'<span class="nav-check" aria-label="Completed">✓</span>':''}</a>`;}).join('');document.querySelector('#progress').value=complete.size;document.querySelector('#progress-label').textContent=`${complete.size} / ${lessons.length}`;}
function setMenu(open){document.querySelector('#sidebar').classList.toggle('open',open);document.querySelector('#menu-toggle').setAttribute('aria-expanded',String(open));document.querySelector('#menu-toggle').setAttribute('aria-label',open?'Close lesson menu':'Open lesson menu');document.querySelector('#menu-shade').hidden=!open;}
document.querySelector('#menu-toggle').onclick=()=>setMenu(!document.querySelector('#sidebar').classList.contains('open'));
document.querySelector('#menu-shade').onclick=()=>setMenu(false);
document.querySelector('#reset-progress').onclick=()=>{complete.clear();saveProgress();const button=document.querySelector('#complete-lesson');if(button)button.textContent='Mark complete ✓';toast('Learning progress reset.');};
function dismissTerm(){if(termPopover){termPopover.trigger.setAttribute('aria-expanded','false');termPopover.element.remove();termPopover=null;}}
function defineTerm(trigger){dismissTerm();const definition=glossary[trigger.dataset.term];if(!definition)return;const element=document.createElement('div');element.className='term-popover';element.id='term-definition';element.setAttribute('role','dialog');element.setAttribute('aria-label',trigger.dataset.term);element.innerHTML=`<button aria-label="Close definition">×</button><strong>${esc(trigger.dataset.term)}</strong><br>${esc(definition)}`;document.body.append(element);const rect=trigger.getBoundingClientRect();element.style.left=`${Math.max(12,Math.min(innerWidth-element.offsetWidth-12,rect.left))}px`;element.style.top=`${Math.max(75,Math.min(innerHeight-element.offsetHeight-12,rect.bottom+10))}px`;trigger.setAttribute('aria-expanded','true');element.querySelector('button').onclick=()=>{dismissTerm();trigger.focus();};termPopover={element,trigger};}
function math(){if(window.renderMathInElement)window.renderMathInElement(content,{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\(',right:'\\)',display:false}],throwOnError:false,strict:'warn'});}
window.addEventListener('load',math);
async function render(){const [id,section]=location.hash.replace(/^#\/?/,'').split('/');const lesson=lessons.find(l=>l.id===id)||lessons[0];if(current===lesson.id&&section){document.getElementById(section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}current=lesson.id;dismissTerm();observer?.disconnect();setMenu(false);drawNav();document.title=`${lesson.title} · Resampler Lab`;const i=lessons.indexOf(lesson),q=lesson.quiz;
content.innerHTML=`<header class="lesson-header"><div class="breadcrumb"><a href="#/start">Guide</a><span>/</span>${esc(lesson.group.toLowerCase())}</div><div class="lesson-kicker">Lesson ${String(i+1).padStart(2,'0')} of ${lessons.length}</div><h1>${esc(lesson.title)}</h1><p class="lesson-subtitle">${esc(lesson.subtitle)}</p><div class="lesson-meta"><span>College-level · step by step</span><span class="pill">${lesson.sections.some(s=>s.lab)?'INTERACTIVE':'READ & REFLECT'}</span></div></header><div class="goal"><b>Learning goal</b>${esc(lesson.goal)}</div>${lesson.sections.map(s=>`<section class="lesson-section" id="${s.id}"><h2>${esc(s.title)}</h2>${s.html}${s.lab?`<div data-lab="${s.lab}"></div>`:''}</section>`).join('')}<section class="quiz" id="check"><div class="quiz-label">CHECK YOUR UNDERSTANDING</div><p class="quiz-prompt">${esc(q.prompt)}</p><div class="quiz-options">${q.options.map((option,j)=>`<button class="quiz-option" data-answer="${j}" aria-pressed="false"><span>${String.fromCharCode(65+j)}</span>${esc(option)}</button>`).join('')}</div><div class="quiz-feedback" role="status" hidden></div></section><section class="sources" id="sources"><h2>Sources for this lesson</h2><ul>${lesson.sources.map(key=>`<li><a href="${references[key][1]}" target="_blank" rel="noopener noreferrer">${esc(references[key][0])} ↗</a></li>`).join('')}</ul></section><footer class="lesson-footer">${i?`<a class="previous" href="#/${lessons[i-1].id}">← ${esc(lessons[i-1].title)}</a>`:'<span></span>'}<button class="button secondary small complete-button" id="complete-lesson">${complete.has(current)?'Completed ✓':'Mark complete ✓'}</button>${i<lessons.length-1?`<a class="button primary small" href="#/${lessons[i+1].id}">${esc(lessons[i+1].title)} →</a>`:'<a class="button primary small" href="#/start">Back to the guide ↑</a>'}</footer><div class="site-footer"><span>Resampler Lab · Research guide</span><span>Live toys + recorded CPU evidence</span></div>`;
document.querySelector('#page-outline').innerHTML=`<b>ON THIS PAGE</b>${lesson.sections.map(s=>`<a href="#/${lesson.id}/${s.id}" data-section="${s.id}">${esc(s.outline||s.title)}</a>`).join('')}<a href="#/${lesson.id}/check" data-section="check">Check your understanding</a><a href="#/${lesson.id}/sources" data-section="sources">Sources</a><p>Definitions are underlined.<br>Select a term to learn more.</p>`;
content.querySelector('#complete-lesson').onclick=e=>{complete.add(current);saveProgress();e.currentTarget.textContent='Completed ✓';toast('Lesson marked complete.');};content.querySelectorAll('[data-answer]').forEach(button=>button.onclick=()=>{const correct=+button.dataset.answer===q.answer;content.querySelectorAll('[data-answer]').forEach(b=>{b.classList.remove('correct','incorrect');b.setAttribute('aria-pressed',String(b===button));});button.classList.add(correct?'correct':'incorrect');const feedback=content.querySelector('.quiz-feedback');feedback.hidden=false;feedback.innerHTML=`<strong>${correct?'Correct.':'Try again.'}</strong> ${esc(q.explanation)}`;});
content.querySelectorAll('[data-term]').forEach(el=>{el.tabIndex=0;el.setAttribute('role','button');el.setAttribute('aria-expanded','false');el.onclick=()=>defineTerm(el);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();defineTerm(el);}};});
content.querySelectorAll('pre').forEach(pre=>{const button=document.createElement('button');button.className='copy-code';button.textContent='Copy';button.onclick=async()=>{try{await navigator.clipboard.writeText(pre.querySelector('code').textContent);button.textContent='Copied ✓';setTimeout(()=>button.textContent='Copy',2000);}catch{toast('Select the code and copy it with your keyboard.');}};pre.append(button);});
math();for(const host of content.querySelectorAll('[data-lab]')){try{await mountLab(host.dataset.lab,host,loadData);}catch(error){host.innerHTML=`<div class="result-error">${esc(error.message)} <button class="button secondary small" id="retry-data">Retry</button></div>`;host.querySelector('button').onclick=render;}}
if(content.querySelector('#hero-demo'))hero(content.querySelector('#hero-demo'));
const repoHost=content.querySelector('#repo-list');if(repoHost){try{const data=await loadData();if(repoHost.isConnected){const sources=data.sources;repoHost.innerHTML=(Array.isArray(sources)?sources:Object.entries(sources).map(([name,v])=>({name,...v}))).map(repo=>{const name=repo.name||repo.id||repo.repository,url=repo.url||`https://github.com/${repo.repository}`,revision=repo.commit||repo.revision;return `<a href="${esc(url.replace(/\.git$/,''))}/tree/${revision}" target="_blank" rel="noopener noreferrer"><span>${esc(name)} ↗</span><code>${esc(revision.slice(0,12))}</code></a>`;}).join('');}}catch{repoHost.innerHTML='<a href="downloads/sources.lock.json" download>Download pinned source revisions ↓</a>';}}
if(current!==lesson.id)return;observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){document.querySelectorAll('.outline a').forEach(a=>a.classList.toggle('active',a.dataset.section===entry.target.id));}},{rootMargin:'-85px 0px -62% 0px'});content.querySelectorAll('.lesson-section,.quiz,.sources').forEach(el=>observer.observe(el));if(section)document.getElementById(section)?.scrollIntoView();else window.scrollTo(0,0);main.focus({preventScroll:true});}
window.addEventListener('hashchange',()=>{searchResults.hidden=true;render();});
const search=document.querySelector('#search'),searchResults=document.querySelector('#search-results');
search.addEventListener('input',()=>{const query=search.value.toLowerCase().trim();if(!query){searchResults.hidden=true;return;}const hits=lessons.flatMap(l=>{const matches=[l.title,l.subtitle,l.goal,...l.sections.map(s=>s.title)].join(' ').toLowerCase().includes(query);return matches?[{title:l.title,description:l.subtitle,href:`#/${l.id}`}]:[];});for(const[term,definition]of Object.entries(glossary))if(term.toLowerCase().includes(query)||definition.toLowerCase().includes(query))hits.push({title:term,description:definition,href:'#/resources/glossary'});searchResults.innerHTML=hits.length?hits.slice(0,10).map(hit=>`<a href="${hit.href}">${esc(hit.title)}<small>${esc(hit.description)}</small></a>`).join(''):'<p>No matches. Try “covariance”, “gradient”, or “benchmark”.</p>';searchResults.hidden=false;});search.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();searchResults.querySelector('a')?.focus();}if(e.key==='Enter'){const first=searchResults.querySelector('a');if(first){location.hash=first.getAttribute('href');searchResults.hidden=true;search.blur();}}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();search.focus();}if(e.key==='Escape'){setMenu(false);searchResults.hidden=true;dismissTerm();search.blur();}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))searchResults.hidden=true;if(termPopover&&!e.target.closest('.term-popover,[data-term]'))dismissTerm();});
if(!location.hash)history.replaceState(null,'','#/start');render();
